        "وتساعد هذه الحلول على إضافة اللون الأخضر دون التضحية بمساحة الأرض. كما يمكن استخدام النباتات الرأسية لتحسين الخصوصية، خصوصًا إذا كانت الحديقة مكشوفة على الشارع أو على مبنى مجاور."
