        "وجود نقطة تركيز يساعد على إعطاء الحديقة هوية واضحة. لكن من الأفضل عدم استخدام عدد كبير من نقاط التركيز القوية في مساحة صغيرة، لأن ذلك يؤدي إلى تشتيت الانتباه."
