        "يمكن استخدامه في: الحدائق الصغيرة، الشرفات الكبيرة، الأسطح، مناطق الجلوس، مناطق لعب الأطفال، والمساحات المحيطة بالمسبح.",
        "لكن اختيار نوع العشب يجب أن يعتمد على الاستخدام المتوقع، وليس الشكل فقط. يجب أيضًا تجهيز السطح بشكل مناسب قبل التركيب، والتأكد من وجود تصريف جيد للمياه."
